// The platform's own message type, declared under its own name: the
// argument assignment the engine generates names it exactly so.
var messages = new List<ChatCompletionsRequestMessageViewModel>
{
    new ChatCompletionsRequestMessageViewModel()
        { Role = "system", Content = $"Answer in a {Input.tone} tone." },
    new ChatCompletionsRequestMessageViewModel()
        { Role = "user", Content = Input.question }
};

return messages.ToArray();

// JSON is not a dynamic object: the way into it is Cast<T> with a
// declared type. AiChunk is that shape, and nothing more of it.
var chunks = (List<string>)#Previous;
string answer = "";
foreach (var chunk in chunks)
{
    var parsed = new JSON(chunk).Cast<AiChunk>();
    var piece = parsed?.choices?[0]?.delta?.content;
    if (!string.IsNullOrEmpty(piece))
        answer += piece;
}

Logger.LogInformation($"joined {chunks.Count} chunks");
return new AskResult() { question = Input.question, answer = answer };

types.AiDelta:
public class AiDelta
{
    /* The piece of text this chunk carries. */
    public string content { get; set; }
}

types.AiChoice:
public class AiChoice
{
    /* One alternative. In practice there is exactly one. */
    public AiDelta delta { get; set; }
}

types.AiChunk:
public class AiChunk
{
    /* One serialised step of the generation, as the function
       answers it: the same shape the chat API streams. */
    public List<AiChoice> choices { get; set; }
}

types.AskResult:
public class AskResult
{
    /* What the caller asked, kept so the answer is self-describing. */
    public string question { get; set; }

    /* The chunks joined back into one text. */
    public string answer { get; set; }
}

